    [6414]={name="Seal of Sylvanas",quality=3,ilvl=29,reqLevel=18,sourceType="quest_reward",instructions="Reward from the quest 'Arugal Must Die'.",zone="Shadowfang Keep",questName="Arugal Must Die",lore="Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain. I shall see to it that his magic is eradicated."},
