    [9449]={name="Manual Crowd Pummeler",quality=3,ilvl=34,reqLevel=29,sourceType="boss_drop",instructions="Drops from Crowd Pummeler 9-60.",zone="Gnomeregan",npc="Crowd Pummeler 9-60",lore="A Gnomeregan oddity whose Use effect grants a huge burst of attack speed. Feral druids kept it for that alone, because it works in cat form -- and it has limited charges, so every use is a decision.",proc="Use: Increases your attack speed by 50% for 30 sec. (3 Min Cooldown)"},
