    [12102]={name="Ring of the Aristocrat",quality=2,ilvl=54,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'The Smoldering Ruins of Thaurissan'. Starts with Royal Historian Archesonus in Ironforge. Objective: Listen to Royal Historian Archesonus recant the history of Thaurissan.",zone="Ironforge",questName="The Smoldering Ruins of Thaurissan",lore="Venture to the smoldering ruins of Thaurissan in the Burning Steppes and gather as much information as possible. It is said that mysterious relics litter the ruins."},
    [12103]={name="Star of Mystaria",quality=3,ilvl=63,reqLevel=58,sourceType="boss_drop",instructions="Drops from Balnazzar.",zone="Stratholme",npc="Balnazzar",proc="Equip: Improves your chance to hit by 1.3%."},
    [12109]={name="Azure Moon Amice",quality=2,ilvl=58,reqLevel=52,sourceType="quest_reward",instructions="Reward from the quest 'The Rise of the Machines'. Pick it over the other reward choices. Starts with Lotwil Veriatus in Badlands. Objective: Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.",zone="Blackrock Depths",questName="The Rise of the Machines",lore="This can't be Argelmach! Argelmach was killed ten years ago. How can I be sure? I was the one who killed him. He was a despicable dwarf, hell-bent on twisting my life's work to meet his diabolical needs."},
    [12110]={name="Raincaster Drape",quality=2,ilvl=58,reqLevel=52,sourceType="quest_reward",instructions="Reward from the quest 'The Rise of the Machines'. Pick it over the other reward choices. Starts with Lotwil Veriatus in Badlands. Objective: Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.",zone="Blackrock Depths",questName="The Rise of the Machines",lore="This can't be Argelmach! Argelmach was killed ten years ago. How can I be sure? I was the one who killed him. He was a despicable dwarf, hell-bent on twisting my life's work to meet his diabolical needs.",proc="Equip: Improves your chance to get a critical strike by 0.5%."},
    [12113]={name="Sunborne Cape",quality=2,ilvl=56,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'Disharmony of Fire'. Pick it over the other reward choices. Starts with Thunderheart in Blackrock Depths. Objective: Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.",zone="Blackrock Depths",questName="Disharmony of Fire",lore="I can taste the foulness in the air that surrounds you. There is another, hidden in the depths of Blackrock, who does control this foulness."},
