    [15443]={name="Kris of Orgrimmar",quality=3,ilvl=18,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'Hidden Enemies'. Pick it over the other reward choices. Starts with Thrall in Ragefire Chasm. Objective: Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.",zone="Orgrimmar",questName="Hidden Enemies",lore="You are one of my lieutenants! Prepare yourself. I will call upon you soon. My time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer."},
    [15444]={name="Staff of Orgrimmar",quality=3,ilvl=18,reqLevel=9,sourceType="quest_reward",instructions="Reward from the quest 'Hidden Enemies'. Pick it over the other reward choices. Starts with Thrall in Ragefire Chasm. Objective: Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.",zone="Orgrimmar",questName="Hidden Enemies",lore="You are one of my lieutenants! Prepare yourself. I will call upon you soon. My time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer."},
